#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <sstream>
#include <algorithm>
#include <functional>
#include <cstring>

enum class Role { ADMIN, OPERATOR, VIEWER };

struct User {
    std::string username;
    Role role;
    std::vector<std::string> allowed_zones;
};

struct DNSQuery {
    std::string domain;
    std::string record_type;
    std::string resolver_hint;
};

class AccessController {
public:
    bool check_zone_access(const User& user, const std::string& zone) {
        if (user.role == Role::ADMIN) return true;
        for (const auto& z : user.allowed_zones) {
            if (zone.find(z) != std::string::npos) return true;
        }
        return false;
    }

    bool can_set_resolver(const User& user) {
        return user.role == Role::ADMIN || user.role == Role::OPERATOR;
    }
};

class DNSProtocolEncoder {
public:
    // Encodes a DNS-over-HTTPS style request line
    std::string encode_request(const DNSQuery& query, const std::string& auth_token) {
        std::string request;
        request += "GET /dns-query?name=" + query.domain;
        request += "&type=" + query.record_type;
        request += " HTTP/1.1\r\n";
        request += "Host: " + query.resolver_hint + "\r\n";
        request += "Authorization: Bearer " + auth_token + "\r\n";
        request += "Accept: application/dns-json\r\n";
        request += "\r\n";
        return request;
    }
};

class InputNormalizer {
public:
    // Normalize domain input - handles IDN and encoding
    std::string normalize_domain(const std::string& input) {
        std::string result;
        for (size_t i = 0; i < input.size(); i++) {
            char c = input[i];
            // Allow alphanumeric, dots, hyphens for domain names
            if (std::isalnum(static_cast<unsigned char>(c)) || c == '.' || c == '-') {
                result += std::tolower(static_cast<unsigned char>(c));
            }
            // Handle percent-encoded sequences
            else if (c == '%' && i + 2 < input.size()) {
                char high = input[i + 1];
                char low = input[i + 2];
                if (std::isxdigit(high) && std::isxdigit(low)) {
                    char decoded = (hex_val(high) << 4) | hex_val(low);
                    // Decode and re-check if it's a valid domain char
                    if (std::isalnum(static_cast<unsigned char>(decoded)) || decoded == '.' || decoded == '-') {
                        result += std::tolower(static_cast<unsigned char>(decoded));
                    }
                    i += 2;
                }
            }
        }
        return result;
    }

    // Sanitize resolver hint - operators can specify custom resolvers
    std::string sanitize_resolver(const std::string& input) {
        std::string result;
        for (size_t i = 0; i < input.size(); i++) {
            char c = input[i];
            // Allow typical hostname/IP characters
            if (std::isalnum(static_cast<unsigned char>(c)) || c == '.' || c == '-' || c == ':') {
                result += c;
            }
            // Handle URL-encoded sequences in resolver field
            else if (c == '%' && i + 2 < input.size()) {
                char high = input[i + 1];
                char low = input[i + 2];
                if (std::isxdigit(high) && std::isxdigit(low)) {
                    char decoded = (hex_val(high) << 4) | hex_val(low);
                    result += decoded;
                    i += 2;
                }
            }
        }
        return result;
    }

private:
    int hex_val(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return 0;
    }
};

class DNSResolver {
public:
    DNSResolver() : normalizer_(), encoder_(), acl_() {}

    std::string resolve(const User& user, const std::string& domain,
                       const std::string& record_type, const std::string& resolver_hint,
                       const std::string& auth_token) {
        // Step 1: Normalize domain
        std::string clean_domain = normalizer_.normalize_domain(domain);
        if (clean_domain.empty()) {
            return "ERROR: Invalid domain";
        }

        // Step 2: Check zone access
        std::string zone = extract_zone(clean_domain);
        if (!acl_.check_zone_access(user, zone)) {
            return "ERROR: Access denied for zone " + zone;
        }

        // Step 3: Determine resolver
        std::string resolver = "dns.default.local";
        if (!resolver_hint.empty()) {
            if (!acl_.can_set_resolver(user)) {
                return "ERROR: Insufficient privileges to set resolver";
            }
            resolver = normalizer_.sanitize_resolver(resolver_hint);
        }

        // Step 4: Build and return the protocol request
        DNSQuery query{clean_domain, record_type, resolver};
        return encoder_.encode_request(query, auth_token);
    }

private:
    std::string extract_zone(const std::string& domain) {
        auto pos = domain.rfind('.');
        if (pos == std::string::npos) return domain;
        auto prev = domain.rfind('.', pos - 1);
        if (prev == std::string::npos) return domain;
        return domain.substr(prev + 1);
    }

    InputNormalizer normalizer_;
    DNSProtocolEncoder encoder_;
    AccessController acl_;
};

int main() {
    User operator_user{"ops_admin", Role::OPERATOR, {"example.com", "internal.net"}};

    DNSResolver resolver;

    // Normal usage
    std::string result = resolver.resolve(
        operator_user, "api.example.com", "A", "8.8.8.8", "tok_abc123");
    std::cout << "Request:\n" << result << std::endl;

    // Attacker-controlled resolver_hint with encoded CRLF
    std::string malicious_hint = "evil.com%0d%0aX-Injected: pwned%0d%0a";
    result = resolver.resolve(
        operator_user, "api.example.com", "A", malicious_hint, "tok_abc123");
    std::cout << "Malicious Request:\n" << result << std::endl;

    return 0;
}
